// Kysely type definitions for cobblr_meta. Mirror the SQL in
// migrations/platform/*.sql.
//
// New table → add a new interface here + Kysely will give you typed
// queries automatically. If a column is generated by Postgres (uuid
// default, timestamptz default) wrap it with Generated<...> so insert
// types don't require you to supply it.

import type { ColumnType, Generated } from "kysely";

export interface UsersTable {
  id: Generated<string>;
  email: string;
  password_hash: string;
  display_name: string;
  active: Generated<boolean>;
  /** True when an admin minted this account with a temp password.
   *  Login succeeds; the response carries the flag and the web
   *  client redirects to /me/force-password-reset until the user
   *  picks their own password. PATCH /me/password clears it. */
  must_reset_password: Generated<boolean>;
  /** uuid of the admin who minted the account (null = self-signup). */
  created_by: string | null;
  created_at: Generated<Date>;
  last_login_at: Date | null;
}

export interface OrgsTable {
  id: Generated<string>;
  name: string;
  slug: string;
  db_name: string;
  db_credentials_encrypted: string | null;
  plan: Generated<"free" | "paid" | "disabled">;
  /** Member-portal config — branding + pinned views shown in the
   *  slimmed-down `/portal/:slug` shell. See
   *  docs/design-decisions/member-portal-and-permissions.md. */
  portal_config: Generated<{
    display_name?: string;
    logo_path?: string | null;
    theme?: "light" | "dark" | "auto";
    pinned_views: string[];
    welcome_markdown?: string;
  }>;
  created_at: Generated<Date>;
  updated_at: Generated<Date>;
}

export interface WorkspaceCapabilityGrantsTable {
  id: Generated<string>;
  org_id: string;
  user_id: string;
  action_id: string;
  granted_at: Generated<Date>;
  granted_by: string | null;
}

export type OrgRole = "owner" | "admin" | "member" | "guest";

export interface OrgMembershipsTable {
  user_id: string;
  org_id: string;
  role: OrgRole;
  joined_at: Generated<Date>;
}

export interface MigrationsTable {
  id: Generated<number>;
  name: string;
  applied_at: Generated<Date>;
}

export interface OrgModulesTable {
  org_id: string;
  module_name: string;
  version: string;
  enabled_at: Generated<Date>;
  last_migration: string | null;
}

export interface EntityPairingsTable {
  id: Generated<string>;
  org_id: string;
  source_kind: string;
  source_id: string;
  target_kind: string;
  target_id: string;
  relationship_kind: string;
  notes: string | null;
  metadata: Generated<Record<string, unknown>>;
  created_at: Generated<Date>;
  created_by: string | null;
}

export interface ApiTokensTable {
  id: Generated<string>;
  user_id: string;
  name: string;
  token_hash: string;
  token_prefix: string;
  expires_at: Date | null;
  last_used_at: Date | null;
  revoked_at: Date | null;
  created_at: Generated<Date>;
}

export interface WorkspaceInvitesTable {
  id: Generated<string>;
  org_id: string;
  invited_by_user: string;
  token: string;
  invited_email: string | null;
  role: OrgRole;
  expires_at: Date | null;
  consumed_at: Date | null;
  consumed_by_user: string | null;
  revoked_at: Date | null;
  created_at: Generated<Date>;
}

// ─────────────────────── platform primitives ──────────────────────

export interface TagsTable {
  id: Generated<string>;
  org_id: string;
  name: string;
  color: string | null;
  created_at: Generated<Date>;
}

export interface TagAssignmentsTable {
  tag_id: string;
  module_name: string;
  entity_type: string;
  entity_id: string;
  attached_at: Generated<Date>;
}

export type AuthMethod = "session" | "api_token" | "system";

export interface ActivityLogTable {
  id: Generated<number>;
  org_id: string;
  user_id: string | null;
  module_name: string | null;
  action: string;
  entity_type: string;
  entity_id: string;
  diff: unknown | null;
  /** How the actor was authenticated. 'system' = internal emitter (wires,
   *  subscribers, boot tasks). */
  auth_method: Generated<AuthMethod>;
  /** Set when auth_method='api_token'; nullable otherwise. */
  api_token_id: string | null;
  occurred_at: Generated<Date>;
}

export type NotificationChannel =
  | "in_app"
  | "browser_push"
  | "email"
  | "discord"
  | "webhook"
  | "slack"
  | "sms";

export type NotificationPriority = "low" | "normal" | "high" | "urgent";

export interface NotificationsTable {
  id: Generated<string>;
  org_id: string;
  user_id: string;
  event_type: string;
  module_name: string | null;
  entity_type: string | null;
  entity_id: string | null;
  message: string;
  link_url: string | null;
  priority: Generated<NotificationPriority>;
  delivered_via: Generated<NotificationChannel[]>;
  read_at: Date | null;
  created_at: Generated<Date>;
}

export interface NotificationSubscriptionsTable {
  id: Generated<string>;
  user_id: string;
  org_id: string;
  /** `*` = wildcard: matches every notification regardless of event_type.
   *  Dispatcher checks exact-match first then falls back to wildcard. */
  event_type: string;
  channel: NotificationChannel;
  enabled: Generated<boolean>;
  /** Only fan out to this subscription if notification.priority is
   *  >= min_priority. low < normal < high < urgent. Default 'low'
   *  (the floor) so legacy subs don't suddenly drop notifications. */
  min_priority: Generated<NotificationPriority>;
  config: unknown | null;
}

// ─────────────────────── Pillar A/B/C/D tables ────────────────────

export interface EntityKindsTable {
  id: string;
  module_name: string;
  display_name: string;
  display_name_plural: string | null;
  icon: string | null;
  fields: unknown;
  detail_route: string | null;
  endpoints: unknown | null;
  version: Generated<string>;
  registered_at: Generated<Date>;
  /** Resolved 6-axis trait assignment (Tangibility, Identity,
   *  Containment, Time, Lifecycle, Persistence). Skipped axes are
   *  absent. Null when the manifest declared no traits. */
  traits: unknown | null;
  /** Preset name (e.g. "owned-thing") if the manifest used profile
   *  shorthand, null if declared raw. Bookkeeping for tooling. */
  profile: string | null;
  /** Cross-module read whitelist (jsonb array of field names) — the
   *  read-time trust boundary. Null = legacy (full fields returned,
   *  deprecation logged on first cross-module read of this kind).
   *  See docs/design-decisions/entity-resolver.md. */
  exposable_fields: unknown | null;
}

export interface CoreRecurrenceEntityStateTable {
  org_id: string;
  kind: string;
  entity_id: string;
  last_fired_at: Date;
  next_due_at: Date | null;
}

/** M1 cross-workspace sharing: source → target read access. */
export interface WorkspaceLinksTable {
  id: Generated<string>;
  source_org_id: string;
  target_org_id: string;
  kinds: string[];
  status: Generated<"pending" | "active" | "revoked">;
  created_by: string;
  created_at: Generated<Date>;
  accepted_at: Date | null;
  revoked_at: Date | null;
  /** M1 v0.2: NULL = never expires. Otherwise the entity-list union
   *  treats a link with expires_at <= now() as inactive at read time
   *  (no scheduled sweep). */
  expires_at: ColumnType<Date | null, Date | null | undefined, Date | null | undefined>;
  /** M1 v0.5: minimum role the viewer must hold in the TARGET
   *  workspace to read the share. NULL = no restriction (every
   *  target member can read, v0.1 default). Values: owner | admin
   *  | member | guest. */
  min_target_role: ColumnType<
    "owner" | "admin" | "member" | "guest" | null,
    "owner" | "admin" | "member" | "guest" | null | undefined,
    "owner" | "admin" | "member" | "guest" | null | undefined
  >;
}

export interface EntityActionsTable {
  id: string;
  module_name: string;
  label: string;
  description: string | null;
  icon: string | null;
  applies_to: unknown;
  invoke_route: string | null;
  invoke_handler: string | null;
  version: Generated<string>;
  registered_at: Generated<Date>;
  /** False for wire-only actions that shouldn't render as a user
   *  button on entity-detail pages (they exist only to be fired by
   *  a wire on an event). */
  user_invokable: Generated<boolean>;
}

export interface EntityActionOrgOverridesTable {
  org_id: string;
  action_id: string;
  applies_to_override: unknown;
  updated_at: Generated<Date>;
  updated_by: string | null;
}

export type TriggerType =
  | "user-invoked"
  | "event"
  | "on-create"
  | "on-update"
  | "on-delete"
  | "schedule";

export interface EntityActionBindingsTable {
  id: Generated<string>;
  org_id: string;
  source_kind: string;
  action_id: string;
  trigger_type: Generated<TriggerType>;
  trigger_event: string | null;
  filter: unknown | null;
  template: string | null;
  args: unknown | null;
  enabled: Generated<boolean>;
  bundle_id: string | null;
  /** Set when this row was contributed by a Pillar-E module's
   *  `contributes.wires`. Cleaned up on module disable. */
  source_module: string | null;
  /** Q1 wire target. JSON value:
   *  - `"self"` — action runs on the source entity (default).
   *  - `{ rel: string, dir?: "in" | "out", kind?: string }` — action
   *    runs on entities discovered by walking entity_pairings from
   *    the source. `dir` defaults to "in".
   *  See docs/design-decisions/wires-and-bundles.md (Q1). */
  target: Generated<unknown>;
  /** Q4: RRULE for schedule-triggered wires (null otherwise).
   *  See docs/design-decisions/wires-and-bundles.md (Q4). */
  trigger_schedule: string | null;
  created_at: Generated<Date>;
  updated_at: Generated<Date>;
}

/** Per-wire scheduling idempotency state, owned by core-recurrence. */
export interface WireScheduleStateTable {
  binding_id: string;
  last_fired_at: Date | null;
  next_due_at: Date | null;
  updated_at: Generated<Date>;
}

export interface BundlesTable {
  id: Generated<string>;
  org_id: string;
  external_id: string;
  name: string;
  version: string;
  author: string | null;
  description: string | null;
  source_url: string | null;
  manifest: unknown;
  installed_at: Generated<Date>;
  /** Tracks whether all install steps completed cleanly.
   *   - "active"  → fully applied.
   *   - "partial" → meta side committed, one or more tenant-side
   *                 steps failed (catalogs, saved_views, lens
   *                 overrides). Re-install to recover.
   *   - "pending" → install in flight (reserved for v0.3 async). */
  install_status: Generated<"active" | "partial" | "pending">;
  install_warnings: Generated<unknown>;
}

export type FieldDefType = "text" | "number" | "boolean" | "date" | "url";

export interface ModuleFieldDefsTable {
  id: Generated<string>;
  org_id: string;
  entity_kind: string;
  name: string;
  display_label: string;
  type: FieldDefType;
  required: Generated<boolean>;
  position: Generated<number>;
  bundle_id: string | null;
  /** Set when this row was contributed by a Pillar-E module's
   *  `contributes.fieldDefs`. Cleaned up on module disable. */
  source_module: string | null;
  /** When type='text', renders as a dropdown of these choices. The
   *  "+ add new" affordance in the UI PATCHes this array. */
  choices: string[] | null;
  /** Built-in renderer id for displaying this field's value in
   *  list rows + detail pages. Same fixed set as
   *  CatalogSchema.field_renderers — color-hex, image-url,
   *  url-link, year, boolean, code, or null (= plain text). */
  renderer: string | null;
  created_at: Generated<Date>;
}

/** Token-keyed lookup so an unauthenticated GET /api/v1/public/:token
 *  can resolve in one query to (org_id, surface_id) without scanning
 *  tenant DBs. Configs themselves live in the tenant DB owned by
 *  core-public-surfaces. */
export interface PublicSurfaceTokensTable {
  token: string;
  org_id: string;
  surface_id: string;
  enabled: Generated<boolean>;
  expires_at: Date | null;
  revoked_at: Date | null;
  created_at: Generated<Date>;
}

export interface WorkspaceModuleInstancesTable {
  id: Generated<string>;
  org_id: string;
  module_name: string;
  instance_name: string;
  display_name: string;
  is_default: Generated<boolean>;
  config: Generated<Record<string, unknown>>;
  created_at: Generated<Date>;
}

export interface EntityKindOverridesTable {
  id: Generated<string>;
  org_id: string;
  /** 'entity_kind' / 'instance' / 'bundle' */
  target_kind: string;
  target_id: string;
  display_label: string | null;
  display_label_plural: string | null;
  icon: string | null;
  hidden: Generated<boolean>;
  nav_order: number | null;
  config: Generated<Record<string, unknown>>;
  created_at: Generated<Date>;
  updated_at: Generated<Date>;
}

export interface CoreLabelsQrTokensTable {
  id: Generated<string>;
  token: string;
  org_id: string;
  entity_kind: string;
  entity_id: string;
  mode: Generated<"navigate" | "action">;
  action_id: string | null;
  auth: Generated<"public" | "session">;
  config: Generated<Record<string, unknown>>;
  created_at: Generated<Date>;
  revoked_at: Date | null;
  expires_at: Date | null;
}

export interface IntegrationInboundTokenLookupTable {
  token: string;
  org_id: string;
  inbound_id: string;
  connector_id: string;
  enabled: Generated<boolean>;
  created_at: Generated<Date>;
}

export interface OrgEncryptionKeysTable {
  org_id: string;
  key_b64: string;
  created_at: Generated<Date>;
}

export interface MetaDB {
  users: UsersTable;
  orgs: OrgsTable;
  org_memberships: OrgMembershipsTable;
  migrations: MigrationsTable;
  org_modules: OrgModulesTable;
  workspace_invites: WorkspaceInvitesTable;
  api_tokens: ApiTokensTable;
  entity_pairings: EntityPairingsTable;
  tags: TagsTable;
  tag_assignments: TagAssignmentsTable;
  activity_log: ActivityLogTable;
  notifications: NotificationsTable;
  notification_subscriptions: NotificationSubscriptionsTable;
  entity_kinds: EntityKindsTable;
  entity_actions: EntityActionsTable;
  entity_action_org_overrides: EntityActionOrgOverridesTable;
  entity_action_bindings: EntityActionBindingsTable;
  wire_schedule_state: WireScheduleStateTable;
  core_recurrence_entity_state: CoreRecurrenceEntityStateTable;
  workspace_links: WorkspaceLinksTable;
  bundles: BundlesTable;
  module_field_defs: ModuleFieldDefsTable;
  public_surface_tokens: PublicSurfaceTokensTable;
  core_queue_jobs: CoreQueueJobsTable;
  auth_magic_tokens: AuthMagicTokensTable;
  workspace_module_instances: WorkspaceModuleInstancesTable;
  entity_kind_overrides: EntityKindOverridesTable;
  core_labels_qr_tokens: CoreLabelsQrTokensTable;
  integration_inbound_token_lookup: IntegrationInboundTokenLookupTable;
  org_encryption_keys: OrgEncryptionKeysTable;
  workspace_capability_grants: WorkspaceCapabilityGrantsTable;
  workspace_roles: WorkspaceRolesTable;
  workspace_role_capabilities: WorkspaceRoleCapabilitiesTable;
  workspace_role_assignments: WorkspaceRoleAssignmentsTable;
  installed_modules: InstalledModulesTable;
}

/** Marketplace v2 — registry of code that can run on this host.
 *  Populated by the loader at boot; distinct from `org_modules`
 *  (per-workspace enable) and `bundles` (data only). See
 *  docs/design-decisions/marketplace.md §4. */
export interface InstalledModulesTable {
  id: Generated<string>;
  name: string;
  version: string;
  band: string;
  source: "image" | "registry" | "manual";
  source_url: string | null;
  source_sha256: string | null;
  signed_by: string | null;
  manifest: unknown;
  installed_at: Generated<Date>;
  installed_by: string | null;
}

/** Custom roles: workspace-defined named bundles of capabilities.
 *  See docs/design-decisions/member-portal-and-permissions.md §7
 *  + 2026-05-25-audit.md S2. Stock roles (owner/admin/member/guest)
 *  stay; custom roles are additive. */
export interface WorkspaceRolesTable {
  id: Generated<string>;
  org_id: string;
  name: string;
  description: string | null;
  created_at: Generated<Date>;
  created_by: string | null;
}

export interface WorkspaceRoleCapabilitiesTable {
  role_id: string;
  action_id: string;
}

export interface WorkspaceRoleAssignmentsTable {
  org_id: string;
  user_id: string;
  role_id: string;
  assigned_at: Generated<Date>;
  assigned_by: string | null;
}

/** core-auth-extensions v0.1: passwordless magic-link tokens. */
export interface AuthMagicTokensTable {
  id: Generated<string>;
  email: string;
  token_hash: string;
  expires_at: Generated<Date>;
  consumed_at: Date | null;
  created_at: Generated<Date>;
  request_ip: string | null;
  request_ua: string | null;
}

/** core-queue v0.1: persistent background work. See
 *  migrations/platform/20260515-020-queue-jobs.sql for the column
 *  semantics + lock-sweep model. */
export interface CoreQueueJobsTable {
  id: Generated<string>;
  org_id: string;
  queue: string;
  payload: Generated<Record<string, unknown>>;
  status: Generated<"queued" | "running" | "done" | "failed">;
  attempts: Generated<number>;
  max_attempts: Generated<number>;
  run_at: Generated<Date>;
  locked_at: Date | null;
  locked_by: string | null;
  completed_at: Date | null;
  failed_at: Date | null;
  error: string | null;
  created_at: Generated<Date>;
}
